import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.Cdp8-jB6.js";const g=JSON.parse('{"title":"ISS gallery mislabels (found 2026-07-11)","description":"","frontmatter":{},"headers":[],"relativePath":"wip/2026-07-11-iss-gallery-mislabels.md","filePath":"wip/2026-07-11-iss-gallery-mislabels.md"}'),s={name:"wip/2026-07-11-iss-gallery-mislabels.md"};function i(l,e,d,n,c,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="iss-gallery-mislabels-found-2026-07-11" tabindex="-1">ISS gallery mislabels (found 2026-07-11) <a class="header-anchor" href="#iss-gallery-mislabels-found-2026-07-11" aria-label="Permalink to &quot;ISS gallery mislabels (found 2026-07-11)&quot;">​</a></h1><p>While building the <code>/programs</code> ESA + ISS pages I hit two data-quality bugs in the <strong><code>fleet-galleries/iss</code></strong> gallery. Surfaced when I went to reuse ISS imagery for the ESA-human and ISS program figures. Both are visible on the live <code>/fleet</code> ISS panel and <code>/colophon</code> credits.</p><h2 id="the-two-bugs" tabindex="-1">The two bugs <a class="header-anchor" href="#the-two-bugs" aria-label="Permalink to &quot;The two bugs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>slot</th><th>served image (what it actually shows)</th><th>provenance credit (<code>image-provenance.json</code>)</th><th>problem</th></tr></thead><tbody><tr><td><code>iss/02.webp</code></td><td><strong>the real ISS</strong> — modern truss + arrays over Earth</td><td><code>File:STS071-744-011 … Full view of the Mir</code> (STS-71, 1995)</td><td><strong>wrong credit</strong> — a correct ISS photo attributed to an STS-71 <em>Mir</em> frame</td></tr><tr><td><code>iss/03.webp</code></td><td><strong>actually Mir</strong> — the dark modular cross-shape, film frame <code>950704 114620 STS71 744 010</code></td><td><code>File:STS071-744-010 … Full view of the Mir</code></td><td><strong>wrong image</strong> — a Mir photo mis-filed in the ISS gallery</td></tr></tbody></table><p><code>iss/01</code> (ISS, Aug 2005), <code>iss/04</code> (station from Crew Dragon) and <code>iss/05</code> (&quot;Step Inside the ISS&quot;) are all correct ISS images — the contamination is limited to slots 02 and 03, both traceable to STS-71 (the first Shuttle-Mir docking, July 1995). Looks like two STS-71 Mir survey frames leaked into the ISS gallery during an early sourcing pass; one slot was later overwritten with a real ISS image but kept the Mir provenance row, the other was never replaced.</p><p>The <code>fleet-galleries/mir</code> gallery itself is clean (its images are correct STS-89/81/74 Mir survey shots).</p><h2 id="fix" tabindex="-1">Fix <a class="header-anchor" href="#fix" aria-label="Permalink to &quot;Fix&quot;">​</a></h2><p>Re-source <strong>both</strong> slots with fresh, known-provenance PD-NASA ISS images (masters → WebP ladder + 1x1, corrected provenance rows), rather than trying to back-derive the true source of the existing <code>iss/02</code> file. Folded into the ISS capstone program slice (task #42) — the ISS page needs strong, correctly- credited imagery regardless, so the fix and the enrichment happen together.</p><p>Status: <strong>FIXED</strong> — both slots re-sourced (ISS-56 2018 fly-around → <code>iss/02</code>, STS-132 2010 → <code>iss/03</code>), full WebP ladder + 1x1 regenerated from new masters, and the two provenance rows corrected to the real PD-NASA sources (tagged <code>corrected-mislabel-iss-gallery</code>). <code>iss/02</code> is now the ISS program hero. Fixed in the ISS program slice.</p>',9)])])}const m=t(s,[["render",i]]);export{g as __pageData,m as default};
